-- preflight for 08_manual_patches (SELECT only) - current published version, in-flight drafts and where each problem is used
-- generated by scripts/prod-open/sat-manual-patches-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; new problem_versions only; no deletes/overwrites; set composition untouched.

select p.id as problem_id, p.status::text as pstatus, pv.version_no as pub_version_no, pv.quality->'auditFix'->>'patch' as already_patch,
  (select count(*) from problem_versions v where v.problem_id = p.id and v.status in ('draft', 'in_review')) as inflight_versions,
  (select string_agg(distinct s.name || ' (' || s.status || ')', ', ') from mock_exam_set_items i join mock_exam_sets s on s.id = i.exam_set_id where i.problem_id = p.id and s.status in ('published', 'draft')) as used_in
from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (array['01d7207e-c5d8-4b93-a2ea-ba5b57b7ff0e','079d2fb7-55f3-455f-a32c-32b252e0da59','0b94e63d-1d30-4fdb-ad23-2ea8895e0978','1473eff6-7ef8-48a6-add7-d241754fdec6','2c4d3a89-40e8-4de9-9d80-7d91657c2674','c93ba362-8516-4e33-b085-ce1b5615787d','dcea79ab-0a4c-4923-8c01-21b87e30d90d','eaac2a72-9970-466d-b509-1c34b9b80a26','58c8d686-47e7-4ce7-95fe-ebfda36d4e60','2d39235f-33fc-44e9-9945-777c44395d5a','3cdc0ad5-a948-4e18-9906-a91e90334fdb','4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','e90ca1b1-6000-4e2d-9346-c6f757d5bed7','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','e1f8fcfb-fbe0-45e7-819a-a38851a50e39','f59b7f57-b596-4235-9902-d8036d9040ff','d1e251f0-cebc-4187-b79c-37da71685423']::uuid[]) order by p.id;
select count(*) as expected_17, count(*) filter (where p.status = 'confirmed') as confirmed, count(*) filter (where exists (select 1 from problem_versions v where v.problem_id = p.id and v.status in ('draft', 'in_review'))) as with_inflight_drafts from problems p where p.id = any (array['01d7207e-c5d8-4b93-a2ea-ba5b57b7ff0e','079d2fb7-55f3-455f-a32c-32b252e0da59','0b94e63d-1d30-4fdb-ad23-2ea8895e0978','1473eff6-7ef8-48a6-add7-d241754fdec6','2c4d3a89-40e8-4de9-9d80-7d91657c2674','c93ba362-8516-4e33-b085-ce1b5615787d','dcea79ab-0a4c-4923-8c01-21b87e30d90d','eaac2a72-9970-466d-b509-1c34b9b80a26','58c8d686-47e7-4ce7-95fe-ebfda36d4e60','2d39235f-33fc-44e9-9945-777c44395d5a','3cdc0ad5-a948-4e18-9906-a91e90334fdb','4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','e90ca1b1-6000-4e2d-9346-c6f757d5bed7','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','e1f8fcfb-fbe0-45e7-819a-a38851a50e39','f59b7f57-b596-4235-9902-d8036d9040ff','d1e251f0-cebc-4187-b79c-37da71685423']::uuid[]);
